import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.util.*;import java.math.*;import java.io.*;import java.nio.charset.StandardCharsets;class PublicExamplesTest{@Test void initialFourAndCurrentChanges(){Object s=TaskBinding.create();assertEquals(Map.of("s1","Math","s2","History"),TaskBinding.subjects(s));assertEquals(2,TaskBinding.teachers(s).size());assertEquals(Set.of("l1","l3"),TaskBinding.teacherIds(s,"t1"));assertEquals(Set.of("l1","l2"),TaskBinding.groupIds(s,"g1"));assertEquals(2,TaskBinding.teacherCount(s,"t1"));TaskBinding.rename(s);assertEquals("Algebra",TaskBinding.subjects(s).get("s1"));assertEquals("Revised",TaskBinding.teachers(s).get("t1"));TaskBinding.room(s);assertEquals("C",TaskBinding.roomOfFirst(s));TaskBinding.cancel(s);assertEquals(1,TaskBinding.teacherCount(s,"t2"));TaskBinding.extra(s);assertEquals(3,TaskBinding.teacherCount(s,"t1"));assertEquals(2,TaskBinding.groupCount(s,"g1"));TaskBinding.holiday(s);assertTrue(TaskBinding.holidayExcluded(s));for(String id:List.of("t1","t2"))assertEquals(TaskBinding.teacherIds(s,id).size(),TaskBinding.teacherCount(s,id));for(String id:List.of("g1","g2"))assertEquals(TaskBinding.groupIds(s,id).size(),TaskBinding.groupCount(s,id));}}
